public void ResetMachineSignal()
        {
            // wafersub
            SignalPool.GetInstance().IsBondNeedChipSignal.ReSet();
            SignalPool.GetInstance().IsWaferAllowPickSignal.ReSet();

            // 流道信号
            SignalPool.GetInstance().AllowDispense1TransferToDispense2Signal.ReSet();
            SignalPool.GetInstance().AllowDispenseTransferToBondSignal.ReSet();
            SignalPool.GetInstance().AllowBondTransferToWaitingUnloadSignal.ReSet();
            SignalPool.GetInstance().AllowWaitingUnloadTransferToOutloadSignal.ReSet();
            SignalPool.GetInstance().TransferToDispense1FinishedSignal.ReSet();
            SignalPool.GetInstance().TransferToDispense2FinishedSignal.ReSet();
            SignalPool.GetInstance().TransferToBondFinishedSignal.ReSet();

            // 上下料
            SignalPool.GetInstance().AllowUnloaderMoveSignal.ReSet();
            SignalPool.GetInstance().AllowLoaderMoveSignal.ReSet();
            SignalPool.GetInstance().LoaderAllowPushSignal.ReSet();
            SignalPool.GetInstance().UnloaderAllowPushSignal.ReSet();

            // 固晶域信号
            SignalPool.GetInstance().IsBondNeedChipSignal.ReSet();
            SignalPool.GetInstance().IsWaferAllowPickSignal.ReSet();
            SignalPool.GetInstance().TransferToBondFinishedSignal.ReSet();
            SignalPool.GetInstance().IsBondPickSucceedSignal.ReSet();
            SignalPool.GetInstance().IsFlipTableAllowPickSignal.ReSet();
            SignalPool.GetInstance().IsAllowDipFluxSignal.ReSet();
            SignalPool.GetInstance().BondDipFluxFinishSignal.ReSet();
            SignalPool.GetInstance().AllowSlideOutSignal.ReSet();
        }

public void ReadyToLog()
        {
            // 日志配置
            if (MachineSoftwareConfiguration.GetInstance().IsWorkLog)
            {
                LogsManager.IsLogInfo = true;
            }
            else
            {
                LogsManager.IsLogInfo = false;
            }
        }

public bool IsAllowTaskClosed()
        {
            this.WorkTasks = new List<Task>();

            // 点胶线程
            if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
            {
                this.WorkTasks.Add(System1Domain.GetInstance().DispenseWorkTask.DispenseTask);
            }

            this.WorkTasks.Add(WaferSystemDomain.GetInstance().WaferSubSystemTask.waferSubTask);
            this.WorkTasks.Add(System2Domain.GetInstance().BondTask.BondWorkTask);
            this.WorkTasks.Add(System2Domain.GetInstance().SlideFluxerTask.SlideFluxTask);
            this.WorkTasks.Add(WaferSystemDomain.GetInstance().FlipTask.FlipTableTask);

            #region 流道

            // 送板机传到上料皮带
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferAutoLoaderToLoadingBeltTask);

            // 上料皮带传到点胶
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferLoadBeltToDispense1Task);

            // 上料仓传到点胶
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferLoaderBinToDispense1Task);

            // 点胶1传到点胶2 
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferDispense1ToDispense2Task);

            // 点胶2 传到Bond
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferDispenseToBondTask);

            // Bond传到下料等待
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferBondToWaitingUnloadTask);

            // 下料等待传到下料皮带
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferWaitingUnloadToUnloadBeltTask);

            // 下料等待传到下料仓
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferWaitingUnloadToUnloadBinTask);

            // 下料皮带到送板机
            this.WorkTasks.Add(TransportDomain.GetInstance().transportTask.transferUnloadBeltToAutoUnloaderTask);

            // 上料仓
            this.WorkTasks.Add(TransportDomain.GetInstance().LoaderTask.loaderTask);

            // 下料仓
            this.WorkTasks.Add(TransportDomain.GetInstance().UnloaderTask.unloaderTask);

            #endregion

            foreach (Task task in this.WorkTasks)
            {
                if (task?.Status == TaskStatus.Running)
                {
                    return false;
                }
            }

            return true;
        }

public bool MachineInitSuccess()
        {
            if (MachineSoftwareConfiguration.GetInstance().IsAxisResetBeforeWork && !this.AllAxisReset)
            {
                AKRSXtraMessageBox.Show("设备轴未复位，请先复位所有轴");

                return false;
            }

            if (!this.PrInitSuccess)
            {
                AKRSXtraMessageBox.Show("设备视觉模板正在初始化，请稍后重试");

                return false;
            }

            if (!this.IsDiskCapacitySufficient())
            {
                return false;
            }

            if (MachineHardwareConfiguration.GetInstance().IsTransportHeatConfigured
                && TransportDomain.GetInstance().TransportController.BondSubSectionController.IsHeaterOpen()
                && !this.PreheatingComplete)
            {
                AKRSXtraMessageBox.Show("垫块预热时间未达到，请稍后重试");

                return false;
            }

            //if (this.LaserEncoderCheck() == false) 
            //{
            //    return false;
            //}

            return true;
        }

public bool CheckOperatingEnvironment()
        {
            // 晶圆域有没有准备好
            if (!WaferSystemDomain.GetInstance().CheckIsReady())
            {
                return false;
            }

            // 固晶域启动自检
            if (!System2Domain.GetInstance().CheckIsReady())
            {
                return false;
            }

            // 点胶域有没有准备好
            if (!System1Domain.GetInstance().CheckIsReady())
            {
                return false;
            }

            // 产品有没有准备好
            if (!ProductConfiguration.GetInstance().IsTransportUnitReady())
            {
                return false;
            }

            // 焊点有没有准备好
            if (!ProductConfiguration.GetInstance().BondPositionConfig.IsBpAssistanceFinish())
            {
                return false;
            }

            // 制程是否准备好
            if (!ProcessDomain.GetInstance().CheckIsReady())
            {
                return false;
            }

            return true;
        }

public void CleanFile(int day)
        {
            try
            {
                DevExpress.Utils.WaitDialogForm waitBeforeLogin = new DevExpress.Utils.WaitDialogForm("请稍后", $"正在删除{day}天前的图片等数据");

                #region 删除文件

                if (!Directory.Exists("D:\\ZX2200存储数据\\"))
                {
                    // 创建文件夹
                    Directory.CreateDirectory("D:\\ZX2200存储数据\\");
                }

                DirectoryInfo dirs = new DirectoryInfo("D:\\ZX2200存储数据\\");

                foreach (DirectoryInfo dir in dirs.GetDirectories())
                {
                    FileSystemInfo[] infos = dir.GetFileSystemInfos();
                    foreach (FileSystemInfo file in infos)
                    {
                        if (DateTime.TryParseExact(
                                file.ToString(),
                                "yyyy-MM-dd",
                                System.Globalization.CultureInfo.CurrentCulture,
                                DateTimeStyles.None,
                                out DateTime dt))
                        {
                            if (dt < DateTime.Now.AddDays(-day))
                            {
                                string newPath = Path.Combine(dir.FullName, file.ToString());
                                Directory.Delete(newPath, true);
                            }
                        }
                    }
                }

                #endregion

                waitBeforeLogin.Close();
            }
            catch (Exception e)
            {
                throw new Exception("定期删除图片失败，请检查是否文件是否已经打开 " + e.Message);
            }
        }

public void Start()
        {
            #region 送板机到入料段(联机)

            // 联机
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online
                || MachineHardwareConfiguration.GetInstance().LoadConfiguration
                == LoadConfigurationEnum.OnlineWithAutoLoader)
            {
                if (this.transferAutoLoaderToLoadingBeltTask == null
                    || this.transferAutoLoaderToLoadingBeltTask.Status != TaskStatus.Running)
                {
                    this.transferAutoLoaderToLoadingBeltTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("送板机传入料段线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 如果在单片上料模式下，没有准备好的料片，就继续等待
                                if (!TransportProvider.PrepareFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                ExcuteResult ret = this.transportController.TransferAutoLoaderToLoading();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(500);
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;

                                        break;
                                }

                                Thread.Sleep(500);
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"送板机传入料段线程：{ex.Message}");
                        }
                    });
                    this.transferAutoLoaderToLoadingBeltTask.ConfigureAwait(false);
                }
            }

            #endregion

            #region 入料段到点胶

            // 未配置自动上下料
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.None)
            {
                if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                           == SubSectionStateEnum.HasMaterial)
                {
                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                        @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                        $"Warning",
                        new[] { "Yes", "No" },
                        new[] { DialogResult.Yes, DialogResult.No });

                    switch (dr)
                    {
                        case DialogResult.Yes:
                            SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                            break;

                        case DialogResult.No:
                            Machine.GetInstance().Stop();
                            break;
                    }
                }
            }
            else if (MachineHardwareConfiguration.GetInstance().LoadConfiguration != LoadConfigurationEnum.LoaderBin)
            {
                // 皮带上料
                // 防止线程多次启动
                if (this.transferLoadBeltToDispense1Task == null || this.transferLoadBeltToDispense1Task.Status != TaskStatus.Running)
                {
                    this.transferLoadBeltToDispense1Task = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("入料皮带传入点胶1线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                    }
                                }

                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                            @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                            $"Warning",
                                            new[] { "Yes", "No" },
                                            new[] { DialogResult.Yes, DialogResult.No });

                                        switch (dr)
                                        {
                                            case DialogResult.Yes:
                                                SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                                break;

                                            case DialogResult.No:
                                                Machine.GetInstance().Stop();
                                                break;
                                        }
                                    }

                                    continue;
                                }

                                // 如果在连续上料模式下，客户点击了不在上料，就继续等待
                                if (!TransportProvider.ContinuousFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                ExcuteResult ret = this.transportController.TransferLoadBeltToDispense();

                                // 如果有料 直接发信号
                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:
                                        // 传送到点胶1结束
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;
                                        break;
                                }

                                if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated == false)
                                {
                                    SignalPool.GetInstance().AllowDispenseTransferToBondSignal.Set();
                                }

                                Thread.Sleep(100);
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"入料传入点胶1线程异常：{ex.Message}");
                        }
                    });

                    this.transferLoadBeltToDispense1Task.ConfigureAwait(false);
                }
            }
            else
            {
                // 配置自动上下料
                // 防止线程多次启动
                if (this.transferLoaderBinToDispense1Task == null || this.transferLoaderBinToDispense1Task.Status != TaskStatus.Running)
                {
                    this.transferLoaderBinToDispense1Task = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("上料仓传入点胶1线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                    }
                                }

                                if (firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                            @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                            $"Warning",
                                            new[] { "Yes", "No" },
                                            new[] { DialogResult.Yes, DialogResult.No });

                                        switch (dr)
                                        {
                                            case DialogResult.Yes:
                                                SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                                break;

                                            case DialogResult.No:
                                                Machine.GetInstance().Stop();
                                                break;
                                        }
                                    }

                                    continue;
                                }

                                // 点击不再上料就一直等待
                                if (!TransportProvider.ContinuousFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                // 等允许推料信号
                                if (!SignalPool.GetInstance().LoaderAllowPushSignal.Wait())
                                {
                                    return;
                                }

                                // 推料到点胶
                                ExcuteResult ret = this.transportController.TransferLoadBinToDispense();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(500);
                                        continue;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        return;

                                    case ExcuteResult.Success:

                                        // 传料完成
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;
                                        break;

                                    case ExcuteResult.Exception:
                                        Machine.GetInstance().Stop();
                                        return;

                                    // 下一片
                                    case ExcuteResult.None:
                                        break;
                                }

                                // 手动复位
                                SignalPool.GetInstance().LoaderAllowPushSignal.ReSet();

                                // 允许料仓移动
                                SignalPool.GetInstance().AllowLoaderMoveSignal.Set();
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"入料仓传入点胶1线程异常：{ex.Message}");
                        }
                    });

                    this.transferLoaderBinToDispense1Task.ConfigureAwait(false);
                }
            }

            #endregion

            #region 点胶1 传到 点胶2
            if (this.transferDispense1ToDispense2Task == null || this.transferDispense1ToDispense2Task.Status != TaskStatus.Running)
            {
                // 本次节点先不用， 下一迭代 加上
                this.transferDispense1ToDispense2Task = Task.Run(() =>
                {
                    CommonUtil.SetCurrentThreadName("点胶1传入点胶2线程");

                    try
                    {
                        while (Signal.WaitStart())
                        {
                            ExcuteResult ret = this.transportController.TransferDispense1ToDispense2();

                            switch (ret)
                            {
                                case ExcuteResult.NoStart:
                                    Thread.Sleep(500);
                                    break;

                                case ExcuteResult.Abort:
                                    Machine.GetInstance().Stop();
                                    break;

                                case ExcuteResult.Success:
                                    // 给Bond 域发信号, Bond轨道传送完成
                                    SignalPool.GetInstance().TransferToDispense2FinishedSignal.Set();
                                    break;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        AKRSXtraMessageBox.Show($"点胶1传入点胶2线程：{ex.Message}");
                    }
                });
                this.transferDispense1ToDispense2Task.ConfigureAwait(false);
            }
            #endregion

            if (this.transferDispenseToBondTask == null || this.transferDispenseToBondTask.Status != TaskStatus.Running)
            {
                this.transferDispenseToBondTask = Task.Run(() =>
                {
                    CommonUtil.SetCurrentThreadName("点胶传入Bond线程");

                    bool firstStart = true;
                    try
                    {
                        // 正在工作
                        while (Signal.WaitStart())
                        {
                            // 第一次启动时，如果dispense table上有料 则直接开始干
                            if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                            {
                                firstStart = false;
                                if (TransportProgram.GetInstance().BondSubSectionProgram.SubSectionState
                                    == SubSectionStateEnum.HasMaterial)
                                {
                                    SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                }
                            }

                            // 第一次启动时，如果Bond table上有料 则直接开始干
                            if (firstStart)
                            {
                                firstStart = false;
                                if (TransportProgram.GetInstance().BondSubSectionProgram.SubSectionState
                                    == SubSectionStateEnum.HasMaterial)
                                {
                                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                        @" 检测到Bond载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                        $"Warning",
                                        new[] { "Yes", "No" },
                                        new[] { DialogResult.Yes, DialogResult.No });

                                    switch (dr)
                                    {
                                        case DialogResult.Yes:
                                            SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                            break;

                                        case DialogResult.No:
                                            Machine.GetInstance().Stop();
                                            break;
                                    }
                                }

                                continue;
                            }


                            ExcuteResult ret = this.transportController.TransferDispenseToBond();

                            switch (ret)
                            {
                                case ExcuteResult.NoStart:
                                    // 提速先注释掉
                                    //Thread.Sleep(50);
                                    break;

                                case ExcuteResult.Abort:
                                    Machine.GetInstance().Stop();
                                    break;

                                case ExcuteResult.Success:
                                    // 给Bond 域发信号, Bond轨道传送完成
                                    SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                    break;
                            }

                            Thread.Sleep(50);
                        }
                    }
                    catch (Exception ex)
                    {
                        AKRSXtraMessageBox.Show($"点胶传入Bond线程：{ex.Message}");
                    }
                });
                this.transferDispenseToBondTask.ConfigureAwait(false);
            }

            if (this.transferBondToWaitingUnloadTask == null || this.transferBondToWaitingUnloadTask.Status != TaskStatus.Running)
            {
                this.transferBondToWaitingUnloadTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("Bond传入等待区线程");

                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                ExcuteResult ret = this.transportController.TransferBondToWaitingUnload();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:

                                        break;

                                    case ExcuteResult.Abort:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Abort");

                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Success");
                                        break;

                                    case ExcuteResult.Exception:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Exception");
                                        Machine.GetInstance().Stop();
                                        break;
                                }

                                Thread.Sleep(100);
                            }
                        }
                        catch (Exception ex)
                        {
                            TransportProvider.RecordTime("Bond传入等待区线程异常", $"{ex.Message}");
                            AKRSXtraMessageBox.Show($"Bond传入等待区线程异常：{ex.Message}");
                        }
                    });
                this.transferBondToWaitingUnloadTask.ConfigureAwait(false);
            }

            #region 等待区到出料

            // 未配置自动上下料
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.None)
            {
                return;
            }
            else if (MachineHardwareConfiguration.GetInstance().LoadConfiguration != LoadConfigurationEnum.LoaderBin)
            {
                if (this.transferWaitingUnloadToUnloadBeltTask == null || this.transferWaitingUnloadToUnloadBeltTask.Status != TaskStatus.Running)
                {
                    this.transferWaitingUnloadToUnloadBeltTask = Task.Run(
                        () =>
                            {
                                CommonUtil.SetCurrentThreadName("等待区传入出料区线程");
                                try
                                {
                                    while (Signal.WaitStart())
                                    {
                                        ExcuteResult ret = this.transportController.TransferWaitingUnloadToUnloadBelt();

                                        switch (ret)
                                        {
                                            case ExcuteResult.NoStart:

                                                break;

                                            case ExcuteResult.Abort:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Abort");

                                                Machine.GetInstance().Stop();

                                                TransportProvider.RecordTime("等待区传入出料区线程", "设备停止");
                                                break;

                                            case ExcuteResult.Success:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Success");
                                                break;

                                            case ExcuteResult.Exception:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Exception");

                                                Machine.GetInstance().Stop();
                                                break;
                                        }

                                        Thread.Sleep(100);
                                    }
                                }
                                catch (Exception ex)
                                {
                                    AKRSXtraMessageBox.Show($"等待区传入出料区线程：{ex.Message}");
                                }
                            });
                    this.transferWaitingUnloadToUnloadBeltTask.ConfigureAwait(false);
                }
            }
            else   // 配置自动上下料
            {
                if (this.transferWaitingUnloadToUnloadBinTask == null || this.transferWaitingUnloadToUnloadBinTask.Status != TaskStatus.Running)
                {
                    this.transferWaitingUnloadToUnloadBinTask = Task.Run(
                        () =>
                        {
                            CommonUtil.SetCurrentThreadName("等待区传入下料仓线程");
                            bool firstStart = true;
                            try
                            {
                                // 正在工作
                                while (Signal.WaitStart())
                                {
                                    // 等允许推料信号
                                    if (!SignalPool.GetInstance().UnloaderAllowPushSignal.Wait())
                                    {
                                        return;
                                    }

                                    // 推料到下料仓
                                    ExcuteResult ret = this.transportController.TransferWaitingUnloadToUnloadBin();

                                    switch (ret)
                                    {
                                        case ExcuteResult.NoStart:
                                            Thread.Sleep(500);
                                            continue;

                                        case ExcuteResult.Abort:
                                            Machine.GetInstance().Stop();
                                            return;

                                        case ExcuteResult.Success:
                                            break;

                                        case ExcuteResult.Exception:
                                            Machine.GetInstance().Stop();
                                            return;
                                    }

                                    Thread.Sleep(200);

                                    // 手动复位
                                    SignalPool.GetInstance().UnloaderAllowPushSignal.ReSet();

                                    // 允许下料仓移动
                                    SignalPool.GetInstance().AllowUnloaderMoveSignal.Set();
                                }
                            }
                            catch (Exception ex)
                            {
                                AKRSXtraMessageBox.Show($"等待区传入下料仓线程：{ex.Message}");
                            }
                        });
                    this.transferWaitingUnloadToUnloadBinTask.ConfigureAwait(false);
                }
            }

            #endregion

            #region 出料段到收板机(联机)

            // 联机
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online || MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.OnlineWithAutoUnloader)
            {
                if (this.transferUnloadBeltToAutoUnloaderTask == null
                    || this.transferUnloadBeltToAutoUnloaderTask.Status != TaskStatus.Running)
                {
                    this.transferUnloadBeltToAutoUnloaderTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("出料段到收板机线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                ExcuteResult ret = this.transportController.TransferUnloadBeltToAutoUnloader();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(100);
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:


                                        break;
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"出料段到收板机线程：{ex.Message}");
                        }
                    });
                    this.transferUnloadBeltToAutoUnloaderTask.ConfigureAwait(false);
                }
            }

            #endregion
        }

private void BarItemStart_ItemClick(object sender, ItemClickEventArgs e)
        {
            this.Enabled = false;

            try
            {
                if (MachineSoftwareConfiguration.GetInstance().RecipeWarningBeforeMachineStart)
                {
                    DialogResult dialog = AKRSXtraMessageBox.Show(
                        $"请确认当前程式：{MachineConfigContext.GetInstance().RecipeName} 是否正确?\r\nOK:继续工作\r\nCancel:退出",
                        "提示",
                        MessageBoxButtons.OKCancel,
                        MessageBoxIcon.Question);

                    if (dialog == DialogResult.Cancel)
                    {
                        return;
                    }
                }

                // 开始生产后，关闭方向盘
                DockPanel dockPanel = this.GetDockPanel("ucGuidMove");
                if (dockPanel != null)
                {
                    dockPanel.Close();
                }

                // 退出单步模式
                MachineStateModel.GetInstance().IsSingleStepWork = false;
                this.BarSwitchSingleStep.Checked = false;

                Machine.GetInstance().Start();
            }
            catch (Exception ex)
            {
                Machine.GetInstance().Stop();
                AKRSXtraMessageBox.Show("启动失败" + ex.Message);
            }
            finally
            {
                this.Enabled = true;
            }
        }

